import sys
from collections import defaultdict

MOD = 998244353

def count_chainwords(n, m, words):
    dp = [0] * (m + 1)
    dp[0] = 1
    prefix_dict = defaultdict(list)

    for word in words:
        prefix_dict[word].append(len(word))

    for i in range(1, m + 1):
        for word, lengths in prefix_dict.items():
            if i >= len(word):
                for length in lengths:
                    dp[i] = (dp[i] + dp[i - length]) % MOD

    total_ways = dp[m]
    result = (total_ways * total_ways) % MOD
    return result

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    m = int(input[1])
    words = input[2:]
    print(count_chainwords(n, m, words))

if __name__ == "__main__":
    main()
